    Q('#mkPrev').onclick = () => { if (pag > 1) { pag--; sel = null; pintaPagina(); } }; Q('#mkNext').onclick = () => { if (pag < nPag) { pag++; sel = null; pintaPagina(); } };
    Q('#mkZmas').onclick = () => { escala = Math.min(4, escala * 1.25); pintaPagina(); }; Q('#mkZmenos').onclick = () => { escala = Math.max(0.2, escala / 1.25); pintaPagina(); };
    Q('#mkIr').onchange = (e) => { const n = Math.max(1, Math.min(nPag, parseInt(e.target.value, 10) || 1)); if (n !== pag) { pag = n; sel = null; } pintaPagina(); };
    Q('#mkAncho').onclick = () => { escala = 1; pintaPagina(); };
    Q('#mkHojaC').onclick = () => { const cv = d.esPdf ? Q('#mkCv') : Q('#mkOf'), h = Q('#mkHoja'), alto = cv ? (d.esPdf ? cv.height : cv.offsetHeight) : 0; if (alto) { escala = Math.max(0.2, Math.min(4, escala * (h.clientHeight - 24) / alto)); pintaPagina(); } };
