    Q('#mkFiltro').onchange = (e) => { filtro = e.target.value; pintaPines(); pintaLista(); };
    w.querySelectorAll('.mlados button').forEach(b => b.onclick = () => { panel = b.dataset.pn; pintaPines(); pintaLista(); });
