    const ni = Q('#mkInc'); if (ni) ni.onclick = () => { if (!d.pag) return N.nuevaIncidencia(p, { contenedor_id: c.id, version_id: vid }, async () => { inc = await api('/api/proyectos/' + pid + '/versiones/' + vid + '/incidencias'); panel = 'incidencias'; pintaPines(); pintaLista(); }); modo = 'incidencia'; Q('#mkHoja').classList.add('poniendo'); N.toast('Haz clic sobre la hoja donde va la chincheta de la incidencia'); };
