    Q('#mkHoja').onclick = (e) => { if (!d.pag || !(modo === 'poner' || modo === 'incidencia')) return; const pines = Q('#mkPines'), r = pines.getBoundingClientRect(); if (e.clientX < r.left || e.clientX > r.right || e.clientY < r.top || e.clientY > r.bottom) return; const pos = { pagina: pag, x: (e.clientX - r.left) / r.width, y: (e.clientY - r.top) / r.height }; if (modo === 'incidencia') { modo = ''; Q('#mkHoja').classList.remove('poniendo'); N.nuevaIncidencia(p, { contenedor_id: c.id, version_id: vid, posicion: Object.assign({ version_id: vid }, pos) }, async () => { inc = await api('/api/proyectos/' + pid + '/versiones/' + vid + '/incidencias'); panel = 'incidencias'; pintaPines(); pintaLista(); }); return; } modo = pos; edita(null); };
